def copiar_datos(apps, schema_editor):
    """Pasa el estado antiguo de cada Mascota a su nuevo ReportePerdida
    y crea el perfil (datos_contacto) de los usuarios que ya existían."""
    Mascota = apps.get_model("mascotas", "Mascota")
    ReportePerdida = apps.get_model("mascotas", "ReportePerdida")
    PerfilUsuario = apps.get_model("mascotas", "PerfilUsuario")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))

    for m in Mascota.objects.all():
        ReportePerdida.objects.get_or_create(
            mascota=m,
            defaults={
                "tipo": "perdida",
                "estado_busqueda": "encontrada" if m.estado == "encontrada" else "activa",
                "fecha_evento": m.fecha_publicacion.date(),
            },
        )
    for u in User.objects.all():
        PerfilUsuario.objects.get_or_create(usuario=u)


